(()=>{const links=[['Home','/'],['Pricing','/pricing/'],['Reseller','/reseller/'],['Apps','/apps/'],['Guides','/guides/'],['Blog','/blog/'],['Contact','/contact/']];const legal=[['About','/about/'],['Privacy','/privacy/'],['Refund','/refund/'],['DMCA','/dmca/']];const make=a=>a.map(x=>`<a href="${x[1]}">${x[0]}</a>`).join('');document.head.insertAdjacentHTML('beforeend',`<style>.brand-logo{display:block;width:auto;height:40px;max-width:180px;object-fit:contain}.global-nav{position:sticky;top:0;z-index:30;background:#0b0f19f2;border-bottom:1px solid #26314a;backdrop-filter:blur(14px)}.global-nav-in{width:min(1120px,calc(100% - 40px));margin:auto;min-height:72px;display:flex;align-items:center;gap:28px}.global-links{display:flex;gap:20px;margin-left:auto;color:#aeb9ce;font-size:.9rem}.global-cta{margin-left:8px}.global-footer{background:#080c15;border-top:1px solid #26314a;padding:46px 0;color:#aeb9ce}.global-footer-in{width:min(1120px,calc(100% - 40px));margin:auto;display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:30px}.global-footer h3{font-size:.78rem;letter-spacing:.13em;text-transform:uppercase;color:#c5b9ff}.global-footer a{display:block;margin:8px 0;font-size:.9rem}@media(max-width:760px){.global-nav-in{min-height:62px;flex-wrap:wrap;padding:11px 0}.global-links{display:none;width:100%;order:4;flex-wrap:wrap;gap:8px;margin:0}.global-links.open{display:flex}.global-links a{padding:8px 10px;background:#12192a;border:1px solid #26314a;border-radius:8px}.global-menu{display:block;margin-left:auto;background:#12192a;border:1px solid #374361;border-radius:8px;color:#fff;padding:8px 11px}.global-cta{display:none}.global-footer-in{grid-template-columns:1fr 1fr}}@media(min-width:761px){.global-menu{display:none}}</style>`);let old=document.querySelector('.nav');if(old)old.remove();document.body.insertAdjacentHTML('afterbegin',`<nav class="global-nav"><div class="global-nav-in"><a class="brand" href="/" aria-label="Mega OTT home"><img class="brand-logo" src="/assets/mega-ott-logo-selected.png" alt="Mega OTT official logo"></a><button class="global-menu" id="globalMenu">Menu ☰</button><div class="global-links" id="globalLinks">${make(links)}</div><a class="button primary global-cta" href="/contact/">Get started</a></div></nav>`);document.querySelector('#globalMenu').onclick=()=>document.querySelector('#globalLinks').classList.toggle('open');document.querySelector('footer')?.remove();document.body.insertAdjacentHTML('beforeend',`<footer class="global-footer"><div class="global-footer-in"><div><a class="brand" href="/" aria-label="Mega OTT home"><img class="brand-logo" src="/assets/mega-ott-logo-selected.png" alt="Mega OTT official logo"></a><p>Mega OTT subscriptions, reseller tools and helpful setup guidance.</p></div><div><h3>Explore</h3>${make(links.slice(1,6))}</div><div><h3>Legal & support</h3>${make([...legal,['Contact','/contact/']])}</div></div></footer>`);})();
(()=>{const page=location.pathname==='/'?'home':location.pathname.replaceAll('/','')||'home';const base='https://megaott.co';const title=document.title||'Mega OTT';const schema={'@context':'https://schema.org','@graph':[{'@type':'Organization','name':'Mega OTT','url':base,'email':'support@reselleriptv.com','contactPoint':{'@type':'ContactPoint','telephone':'+212670779271','contactType':'customer support'}},{'@type':'Service','name':title,'provider':{'@type':'Organization','name':'Mega OTT'},'url':base+location.pathname,'description':'Mega OTT subscription, reseller and device setup services.'},{'@type':'Product','name':'Mega OTT Subscription','brand':{'@type':'Brand','name':'Mega OTT'},'url':base+'/pricing/'},{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':'How do I contact Mega OTT?','acceptedAnswer':{'@type':'Answer','text':'Contact Mega OTT on WhatsApp for purchase, trial and reseller requests.'}},{'@type':'Question','name':'How do Mega OTT reseller credits work?','acceptedAnswer':{'@type':'Answer','text':'One reseller credit represents 12 months for one customer line.'}}]}]};const el=document.createElement('script');el.type='application/ld+json';el.text=JSON.stringify(schema);el.dataset.page=page;document.head.appendChild(el);})();
(()=>{const canonical=document.createElement('link');canonical.rel='canonical';canonical.href='https://megaott.co'+(location.pathname.endsWith('index.html')?location.pathname.replace('index.html',''):location.pathname);document.head.appendChild(canonical);document.documentElement.lang='en';})();
